INSERT INTO `guilds` (`name`, `ownerid`, `creationdata`, `motd`)
SELECT 'Antica', `id`, UNIX_TIMESTAMP(), 'Hold the west temple.' FROM `players` WHERE `name` = 'Antica EK 1';
INSERT INTO `guilds` (`name`, `ownerid`, `creationdata`, `motd`)
SELECT 'Amera', `id`, UNIX_TIMESTAMP(), 'Hold the east temple.' FROM `players` WHERE `name` = 'Amera EK 1';

INSERT INTO `guild_membership` (`player_id`, `guild_id`, `rank_id`, `nick`)
SELECT p.`id`, g.`id`, r.`id`, ''
FROM `players` p
JOIN `guilds` g ON ((p.`name` LIKE 'Antica %' AND g.`name` = 'Antica') OR (p.`name` LIKE 'Amera %' AND g.`name` = 'Amera'))
JOIN `guild_ranks` r ON r.`guild_id` = g.`id` AND r.`level` = IF(p.`id` = g.`ownerid`, 3, 1);
